insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g6$th_8$g6$, $g7$A/an і the: перша та друга згадка$g7$, $g8$elementary$g8$, $g9$formula$g9$, $g10${"step":"Перша й друга згадка","kicker":"Головна розвилка","lead":"Говоримо про щось <b>уперше</b> — вживаємо a/an. Співрозмовник уже знає, про що йдеться, — <b>the</b>.","tiles":[{"role":"1-ша згадка","label":"a / an","tone":"opinion"},{"role":"2-га згадка","label":"the","tone":"colour"}],"legend":[{"tone":"opinion","label":"один із багатьох, ще невідомий"},{"tone":"colour","label":"конкретний, уже відомий"}],"examples":[{"text":"I had <b>a</b> sandwich and <b>an</b> apple. <b>The</b> sandwich wasn't very good, but <b>the</b> apple was nice.","plain":"I had a sandwich and an apple. The sandwich wasn't very good, but the apple was nice.","note":"a → the"},{"text":"<b>A</b> man and <b>a</b> woman were sitting opposite me. <b>The</b> man was American.","plain":"A man and a woman were sitting opposite me. The man was American.","note":"a → the"},{"text":"Paula is looking for <b>a</b> job. Did she get <b>the</b> job she applied for?","plain":"Paula is looking for a job. Did she get the job she applied for?","note":"a → the"}],"note":"<i>The</i> вживаємо й тоді, коли предмет конкретизований: <i>Tim sat down on <b>a</b> chair</i> (один із багатьох) — <i>Tim sat down on <b>the</b> chair nearest the door</i> (конкретний)."}$g10$::jsonb, null, 1
