insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g12$th_9$g12$, $g13$The, коли зрозуміло із ситуації$g13$, $g14$elementary$g14$, $g15$cases$g15$, $g16${"step":"The із ситуації","kicker":"Контекст замість першої згадки","lead":"Коли з контексту ясно, про який предмет чи людину йдеться, вживаємо <b>the</b> навіть при першій згадці.","cards":[{"icon":"▣","title":"У кімнаті","text":"Світло, підлога, двері — одні на всіх.","example":"Turn off <b>the</b> light, please.","examplePlain":"Can you turn off the light, please?"},{"icon":"⌂","title":"У місті","text":"Банк, пошта, вокзал, лікар, дантист — «наші» в цьому місці.","example":"I took a taxi to <b>the</b> station.","examplePlain":"I took a taxi to the station."},{"icon":"☺","title":"Свій лікар","text":"the doctor = той лікар, до якого ми звикли ходити.","example":"She's gone to <b>the</b> doctor.","examplePlain":"Clare isn't very well. She's gone to the doctor."}],"axis":{"title":"Той самий іменник, різний артикль","points":[{"label":"the","text":"I have to go to <b>the</b> bank today."},{"label":"a","text":"Is there <b>a</b> bank near here?"},{"label":"the","text":"I don't like going to <b>the</b> dentist."},{"label":"a","text":"My sister is <b>a</b> dentist."}],"note":"A/an називає, ЩО це за річ чи професія. The вказує на конкретний предмет."}}$g16$::jsonb, null, 2
