insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g18$th_10$g18$, $g19$A/an у значенні «за»$g19$, $g20$elementary$g20$, $g21$formula$g21$, $g22${"step":"A/an = «за»","kicker":"Частота, швидкість, ціна","lead":"Для частоти, швидкості й ціни на одиницю вживаємо <b>a/an</b> у значенні «за».","tiles":[{"role":"частота","label":"once / twice + a","tone":"opinion"},{"role":"ціна","label":"£1.50 + a kilo","tone":"colour"},{"role":"швидкість","label":"50 km + an hour","tone":"size"}],"legend":[{"tone":"opinion","label":"once a week, three times a day"},{"tone":"colour","label":"£1.50 a kilo"},{"tone":"size","label":"50 kilometres an hour"}],"examples":[{"text":"'How often do you go to the cinema?' 'About once <b>a</b> month.'","plain":"How often do you go to the cinema? About once a month.","note":"частота"},{"text":"'How much are those potatoes?' '£1.50 <b>a</b> kilo.'","plain":"How much are those potatoes? One pound fifty a kilo.","note":"ціна"},{"text":"Helen works eight hours <b>a</b> day, six days <b>a</b> week.","plain":"Helen works eight hours a day, six days a week.","note":"на день / тиждень"}],"note":"Перед голосним звуком — <b>an</b>: <i>50 kilometres <b>an</b> hour</i>."}$g22$::jsonb, null, 3
