insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g24$th_11$g24$, $g25$The з унікальними об'єктами$g25$, $g26$intermediate$g26$, $g27$formula$g27$, $g28${"step":"Унікальні речі","kicker":"Єдиний у світі","lead":"Коли предмет у світі <b>єдиний</b>, вживаємо the. Так само перед <b>same</b> і порядковими числівниками.","tiles":[{"role":"єдиний","label":"the sun","tone":"colour"},{"role":"найвищий ступінь","label":"the longest","tone":"origin"},{"role":"порядковий","label":"the tenth","tone":"size"}],"legend":[{"tone":"colour","label":"the sun, the moon, the world, the sky, the sea"},{"tone":"origin","label":"What's the longest river in Europe?"},{"tone":"size","label":"Our apartment is on the tenth floor."}],"examples":[{"text":"Your sweater is <b>the same</b> colour as mine.","plain":"Your sweater is the same colour as mine.","note":"НЕ same colour"},{"text":"<b>The</b> sun is <b>a</b> star.","plain":"The sun is a star.","note":"the — єдина, a — що це за річ"},{"text":"There are millions of stars in <b>space</b>.","plain":"There are millions of stars in space.","note":"space без the"}],"note":"Без the: <i>Earth</i> як планета (<i>Which planet is nearest Earth?</i>) і <i>space</i> як космос.","tabs":[{"title":"Список унікальних","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Майже завжди з the:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">the sun · the moon · the earth · the world · the universe · the sky · the sea · the ground · the environment · the internet · the equator</div>"}]}$g28$::jsonb, null, 4
