select id, $g30$th_12$g30$, $g31$The cinema, television, breakfast, Platform 5$g31$, $g32$intermediate$g32$, $g33$cases$g33$, $g34${"step":"Групи-пастки","kicker":"Що найчастіше плутають","lead":"Чотири окремі групи, де артикль не очевидний.","cards":[{"icon":"▶","title":"the cinema / theatre / radio","text":"Не обов'язково конкретний кінотеатр: ходимо туди «взагалі».","example":"I go to <b>the</b> cinema a lot.","examplePlain":"I go to the cinema a lot."},{"icon":"▭","title":"television / TV","text":"Без the. Але the television = сам телевізор як прилад.","example":"I watch <b>television</b> a lot.","examplePlain":"I watch television a lot."},{"icon":"◔","title":"breakfast / lunch / dinner","text":"Без the. З прикметником — a/an.","example":"We had <b>a</b> very nice lunch.","examplePlain":"We had a very nice lunch."},{"icon":"№","title":"Noun + number","text":"Без the: Platform 5, size 43, Room 126, page 29, question 3, Gate 10.","example":"Platform <b>5</b>","examplePlain":"Platform 5"}]}$g34$::jsonb, null, 5
