insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g36$th_13$g36$, $g37$School чи the school?$g37$, $g38$intermediate$g38$, $g39$pairs$g39$, $g40${"step":"Призначення чи будівля","kicker":"Місце за функцією","lead":"Коли йдеться про <b>призначення</b> місця — артикля немає. Коли про <b>саму будівлю</b> — вживаємо the.","groups":[{"title":"Prison","note":"в'язень → відвідувач","items":[["in prison","to the prison"]]},{"title":"Hospital","note":"пацієнт → гість","items":[["to hospital","to the hospital"]]},{"title":"Church","note":"на службу → будівля","items":[["to church","to the church"]]},{"title":"Bed","note":"спати → меблі","items":[["go to bed","sit on the bed"]]},{"title":"Sea","note":"у плаванні → водойма","items":[["at sea","swim in the sea"]]},{"title":"Work / home","note":"завжди без the","items":[["go to work","go home"],["finish work","be at home"]]}],"notes":["<b>Без the (за призначенням):</b> school, prison/jail, hospital, university, college, church, bed, work, home, sea.","<b>work</b> у значенні «робота» НІКОЛИ не бере the: <i>go to work</i>. А <b>home</b> без «to»: <i>go home</i> (НЕ <s>to home</s>).","<i>Ken's brother is in prison for robbery.</i> (в'язень) — <i>Ken went to the prison to visit his brother.</i> (відвідувач)"]}$g40$::jsonb, null, 6
