insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g42$th_14$g42$, $g43$Children чи the children: загальне й конкретне$g43$, $g44$intermediate$g44$, $g45$formula$g45$, $g46${"step":"Загальне й конкретне","kicker":"Нульовий артикль","lead":"Коли говоримо про речі чи людей <b>загалом</b>, артикль НЕ вживається. The з'являється, коли йдеться про конкретну групу.","tiles":[{"role":"загальне","label":"plural / uncountable","tone":"neutral"},{"role":"конкретне","label":"the + noun","tone":"colour"}],"legend":[{"tone":"neutral","label":"без артикля"},{"tone":"colour","label":"саме ці, відомі нам"}],"examples":[{"text":"I'm afraid of <b>dogs</b>. / We took <b>the children</b> to the zoo.","plain":"I'm afraid of dogs. We took the children to the zoo.","note":"взагалі / саме ці"},{"text":"<b>Sugar</b> isn't very good for you. / Can you pass <b>the sugar</b>, please?","plain":"Sugar isn't very good for you. Can you pass the sugar, please?","note":"взагалі / цей цукор"},{"text":"Doctors are usually paid more than teachers.","plain":"Doctors are usually paid more than teachers.","note":"загальне твердження"}],"note":"<b>most</b> + іменник — без the: <i>Most shops accept credit cards.</i> (НЕ <s>The most shops</s>).","tabs":[{"title":"Предмети, спорт, музика","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Шкільні предмети, спорт і музика — без the:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">history · physics · football · classical music</div>"},{"title":"Уточнення","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Уточнення не завжди додає the. Це все ще загальна ідея:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">I like working with <b>people who say what they think</b>.</div>"}]}$g46$::jsonb, null, 7
