insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g48$th_18$g48$, $g49$Стоп-калька: де НЕ ставлять the$g49$, $g50$intermediate$g50$, $g51$traps$g51$, $g52${"step":"Стоп-калька","kicker":"Типові помилки українських учнів","lead":"Найчастіша помилка — <b>зайвий артикль</b> там, де його бути не може: перед спортом, мовами, <i>work</i>, присвійними займенниками.","items":[{"title":"«Я люблю теніс»","bad":"I love the tennis.","good":"I love <b>tennis</b>.","goodPlain":"I love tennis.","rule":"Види спорту та ігри — без the."},{"title":"«Ти говориш французькою?»","bad":"Can you speak the French?","good":"Can you speak <b>French</b>?","goodPlain":"Can you speak French?","rule":"Мови без the. Але <i>The French language is beautiful.</i> — з іменником language артикль потрібен."},{"title":"«Це моя книга»","bad":"That is the my book.","good":"That is <b>my</b> book.","goodPlain":"That is my book.","rule":"Присвійний займенник і the не вживаються разом."},{"title":"«Більшість студентів складають»","bad":"The most students pass.","good":"<b>Most</b> students pass.","goodPlain":"Most students pass.","rule":"<i>most</i> + іменник — без the."},{"title":"«Я мушу йти на роботу»","bad":"I have to go to the work.","good":"I have to go to <b>work</b>.","goodPlain":"I have to go to work.","rule":"<i>work</i> у значенні «робота» НІКОЛИ не бере the."},{"title":"«Вона приїхала літаком»","bad":"She came by the plane.","good":"She came by <b>plane</b>.","goodPlain":"She came by plane.","rule":"<i>by</i> + транспорт — без артикля. Але <i>She was on the bus.</i>"},{"title":"«Ми пообідали»","bad":"We had the lunch.","good":"We had <b>lunch</b>.","goodPlain":"We had lunch.","rule":"Прийоми їжі — без the."}]}$g52$::jsonb, null, 8
