select id, $g54$th_15$g54$, $g55$Назви без the: люди, країни, міста, гори$g55$, $g56$advanced$g56$, $g57$formula$g57$, $g58${"step":"Імена й країни","kicker":"Географія: без артикля","lead":"Імена людей і більшість географічних назв вживаються <b>без артикля</b>.","tiles":[{"role":"без the","label":"Africa · France · Cairo","tone":"neutral"},{"role":"титул + ім'я","label":"Mr Johnson","tone":"opinion"}],"legend":[{"tone":"neutral","label":"континенти · країни · штати · острови · міста · окремі гори · озера"},{"tone":"opinion","label":"Uncle Robert, President Johnson, Saint Catherine"}],"examples":[{"text":"<b>Africa</b>, <b>Europe</b>, <b>South America</b>; <b>France</b>, <b>Brazil</b>, <b>Texas</b>","plain":"Africa, Europe, South America; France, Brazil, Texas","note":"континенти, країни, штати"},{"text":"<b>Sicily</b>, <b>Bermuda</b>; <b>Cairo</b>, <b>New York</b>; <b>Everest</b>, <b>Etna</b>","plain":"Sicily, Bermuda; Cairo, New York; Everest, Etna","note":"острови, міста, гори"},{"text":"<b>Mount</b> Everest, <b>Lake</b> Superior — but: They live near <b>the</b> lake.","plain":"Mount Everest, Lake Superior. They live near the lake.","note":"Mount / Lake"}],"note":"Титул + ім'я — без the: <i>Doctor Johnson</i>. Але <i>We called <b>the</b> doctor.</i>","tabs":[{"title":"Винятки з the","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Назви зі словами Republic, Kingdom, States — з the:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">the Czech Republic · the United Kingdom · the United States</div>"},{"title":"Сторони світу","html":"<div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">northern Europe (без the)<br>the north of Brazil · the Middle East · the Far East</div>"}]}$g58$::jsonb, null, 9
