insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g60$th_16$g60$, $g61$Назви З the: океани, річки, пустелі, множина$g61$, $g62$advanced$g62$, $g63$cases$g63$, $g64${"step":"Назви з the","kicker":"Географія: з артиклем","lead":"Водойми, пустелі, гірські пасма та всі назви у <b>множині</b> беруть the.","cards":[{"icon":"≋","title":"Океани, моря, канали","text":"the + океан, море, канал.","example":"the Atlantic · the Red Sea · the Suez Canal","examplePlain":"the Atlantic, the Red Sea, the Suez Canal"},{"icon":"∿","title":"Річки","text":"Усі річки з the.","example":"the Nile · the Thames · the Volga","examplePlain":"the Nile, the Thames, the Volga"},{"icon":"◬","title":"Гірські пасма","text":"Пасма — з the, окремі гори — без.","example":"the Alps · the Andes · the Urals","examplePlain":"the Alps, the Andes, the Urals"},{"icon":"☼","title":"Пустелі","text":"the + пустеля.","example":"the Sahara · the Gobi Desert","examplePlain":"the Sahara, the Gobi Desert"},{"icon":"⁂","title":"Групи островів","text":"Множинні назви.","example":"the Canaries · the Bahamas","examplePlain":"the Canaries, the Bahamas"},{"icon":"⚑","title":"Країни у множині, родини","text":"Множина — завжди з the.","example":"the Netherlands · the Taylors","examplePlain":"the Netherlands, the Taylors"}]}$g64$::jsonb, null, 10
